export const GLOSSARY_SHARD = Object.freeze({"tokenomics":{"slug":"tokenomics","cat":"basics","en":"Tokenomics","contentLocale":"ja","term":"トークノミクス","aka":["Tokenomics","トークンエコノミクス"],"short":"トークノミクスとは、暗号資産トークンの供給量、配分、発行スケジュール、用途、焼却などをまとめた経済設計の全体像のことです。","body":[["トークノミクスで確認すべき主な項目は、最大供給量と現在の",["流通量","circulating-supply"],"、チーム・投資家・コミュニティなどへの配分比率、ロックと",["アンロック","token-unlock"],"の予定、新規発行（インフレ）の割合、そしてトークンの用途です。"],["用途とは、手数料の支払い、",["ステーキング","staking"],"、ガバナンス投票、手数料割引など、トークンを持つ理由のことです。需要が生まれる仕組みが弱いのに供給が増え続ける設計では、価格に継続的な下押し圧力がかかりやすくなります。"],["配分も重要です。チームと初期投資家の割合が大きく、ロック期間が短い場合、アンロックのたびに大量の売りが出る可能性があります。逆に、",["トークンバーン（焼却）","token-burn"],"や買い戻しで供給を減らす設計のプロジェクトもあります。ホワイトペーパーの数字は、データサイトの流通量と照らし合わせて確認しましょう。"]],"example":["例えば、総供給量10億枚のトークンで、チーム20%、投資家15%、コミュニティ報酬40%、財団25%に配分されているとします。チームと投資家の合計3.5億枚が、",["上場","token-listing"],"1年後から2年かけて毎月均等にアンロックされるなら、毎月約1,458万枚が新たに売却可能になります。"],"mistakes":["配分の円グラフだけを見て、アンロックの時期を確認しないこと。","新規発行によるインフレ率を考えずに、高いステーキング利回りだけに注目すること。","「バーンがある」と聞いただけで、供給が必ず減ると考えること。"],"faq":[{"q":"良いトークノミクスとはどのようなものですか？","a":"一般に、配分が特定の人に偏りすぎず、アンロックが段階的で、トークンを持つ実需がある設計が評価されやすいです。ただし、それだけで価格が保証されるわけではありません。"},{"q":"トークノミクスはどこで確認できますか？","a":"プロジェクトのホワイトペーパーや公式ドキュメント、トークン情報をまとめたデータサイトで確認できます。"}],"title":"トークノミクスとは？見るべきポイントを解説","description":"トークノミクスの意味と、供給量・配分・アンロック・用途など、トークンを評価するときに見るべきポイントを解説します。","related":[["circulating-supply","流通供給量","流通供給量とは、現在市場で自由に取引できる状態にある暗号資産の枚数のことで、ロック中のトークンやまだ発行されていない分は含まれません。"],["token-unlock","トークンアンロック","トークンアンロックとは、チームや投資家などに配分されロックされていたトークンが、決められたスケジュールに従って売却や移転できるようになることです。"],["fully-diluted-valuation","完全希薄化後時価総額（FDV）","完全希薄化後時価総額（FDV）とは、トークンの現在価格に最大供給量（または総供給量）を掛けた値で、将来すべてのトークンが流通した場合の評価額を示します。"],["token-burn","トークンバーン（焼却）","トークンバーン（焼却）とは、トークンを誰も取り出せないアドレスに送ったりコントラクトで消滅させたりして、流通から永久に取り除くことです。"],["governance-token","ガバナンストークン","ガバナンストークンとは、DeFiやDAOなどのプロジェクトで、運営方針や仕様変更に関する投票に参加する権利を表すトークンです。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"order-book":{"slug":"order-book","cat":"trading","en":"Order book","contentLocale":"ja","term":"板（オーダーブック）","aka":["オーダーブック","板情報","Order book"],"short":"板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。","body":[["板は、買い注文（ビッド）と売り注文（アスク）の2つに分かれます。買い注文のうち最も高い価格が最良買い気配、売り注文のうち最も安い価格が最良売り気配で、その差が",["スプレッド","bid-ask-spread"],"です。各価格には、待っている注文の数量が表示されます。"],[["指値注文","limit-order"],"を出すと、すぐに約定しない限り板に並び、相手が来るのを待ちます。",["成行注文","market-order"],"は、板に並んでいる注文を有利な価格から順に消化して約定します。そのため、板が薄い（注文量が少ない）と、成行注文の約定価格が大きくずれる",["スリッページ","slippage"],"が起こります。"],["板を見ると、相場の",["流動性","liquidity"],"や、特定の価格に大きな注文が集まっているかが分かります。ただし、大口注文は約定前に取り消されることもあり、見せかけの注文で相場を動かそうとする行為もあるため、板の数字だけで判断しないことが大切です。"]],"example":["例えば、",["ETH","ethereum"],"/USDTの売り板が「3,000ドルに2 ETH、3,005ドルに3 ETH、3,010ドルに5 ETH」だったとします。成行で4 ETHを買うと、3,000ドルで2 ETH、3,005ドルで2 ETHが約定し、合計12,010ドル、平均価格は3,002.5ドルです。最良売り気配の3,000ドルより、1 ETHあたり2.5ドル高く買ったことになります。"],"mistakes":["板の厚さを確認せずに大きな成行注文を出すこと。","板に表示された大口注文が必ず約定すると信じて売買を判断すること。","ビッドとアスクを取り違え、売りたい価格を買い板ではなく売り板で探すこと。"],"faq":[{"q":"板が厚い・薄いとはどういう意味ですか？","a":"板が厚いとは各価格に多くの注文が並んでいる状態で、大きな注文でも価格が動きにくいことを指します。板が薄いと、少ない注文でも価格が大きく動きます。"},{"q":"販売所には板がありますか？","a":"販売所は取引所が相手となって価格を提示する形式なので、利用者同士の板はありません。板を使って売買するのは取引所（板取引）の形式です。"}],"title":"板（オーダーブック）とは？見方と使い方を解説","description":"暗号資産取引の板（オーダーブック）の意味と見方、成行注文が約定する仕組み、板の厚さとスリッページの関係を解説します。","related":[["bid-ask-spread","スプレッド（売買価格差）","スプレッドとは、板の最良買い気配（ビッド）と最良売り気配（アスク）の価格差のことで、売買のたびに実質的にかかるコストの一つです。"],["limit-order","指値注文","指値注文とは、売買したい価格を自分で指定し、その価格かそれより有利な価格になったときにだけ約定させる注文方法です。"],["market-order","成行注文","成行注文とは、価格を指定せずに、その時点で板にある最も有利な価格から順に、すぐに売買を成立させる注文方法です。"],["liquidity","流動性（リクイディティ）","流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。"],["slippage","スリッページ","スリッページとは、注文時に想定していた価格と実際に約定した価格との差のことで、主に成行注文や値動きの激しい局面で発生します。"]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"画面に表示された価格が、なぜ約定価格と違うのか？"},"coin":null,"tool":null,"cta":true},"liquidity":{"slug":"liquidity","cat":"trading","en":"Liquidity","contentLocale":"ja","term":"流動性（リクイディティ）","aka":["リクイディティ","liquidity"],"short":"流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。","body":[["流動性が高い銘柄では、買いたい人と売りたい人が常に大勢いるため、まとまった数量でも想定に近い価格で約定します。逆に流動性が低い銘柄では、少し大きな注文を出しただけで板を何段も食い、平均約定価格が不利になります。これが",["スリッページ","slippage"],"です。"],["流動性を測る目安は主に3つあります。最良の買い気配と売り気配の差である",["スプレッド","bid-ask-spread"],"、各価格帯に並んでいる注文量である板の厚み、そして",["取引量","trading-volume"],"です。ただし取引量は水増しされることもあるため、板の厚みとスプレッドを合わせて見るのが確実です。"],["同じ銘柄でも、取引所や",["通貨ペア","trading-pair"],"、時間帯によって流動性は変わります。BTCやETHの主要ペアは一般に厚く、",["上場","token-listing"],"したばかりのトークンや小型銘柄は薄くなりがちです。",["分散型取引所","dex"],"では板の代わりに流動性プールの規模が流動性を決めます。"]],"example":"ある小型トークンが1.00 USDTで取引されていて、売り板に1.00で2,000枚、1.02で3,000枚、1.05で5,000枚が並んでいるとします。10,000枚を成行で買うと、支払いは2,000＋3,060＋5,250＝10,310 USDTで、平均約定価格は約1.031 USDTです。表示価格より約3.1%高く買ったことになります。厚い板なら同じ注文でもほぼ1.00付近で約定します。","mistakes":["チャートの価格だけを見て、板の厚みを確認せずに大きな成行注文を出してしまう。","取引量が多いから流動性も高いと判断し、スプレッドや板の薄さを見落とす。","週末や深夜など参加者が少ない時間帯でも、日中と同じ流動性があると考える。"],"faq":[{"q":"流動性が低いと何が問題ですか？","a":"注文が想定より不利な価格で約定しやすく、売りたいときにすぐ売れないことがあります。急変時には価格が大きく飛ぶこともあります。"},{"q":"流動性はどこで確認できますか？","a":"取引画面の板とスプレッドで確認できます。注文したい数量を約定させるのに板を何段食うかを見ると、実際のコストがわかります。"}],"title":"暗号資産の流動性とは？意味と見分け方","description":"流動性の意味、スプレッドや板の厚みでの見分け方、流動性が低い銘柄でスリッページが起きる仕組みを計算例付きで解説します。","related":[["order-book","板（オーダーブック）","板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。"],["slippage","スリッページ","スリッページとは、注文時に想定していた価格と実際に約定した価格との差のことで、主に成行注文や値動きの激しい局面で発生します。"],["bid-ask-spread","スプレッド（売買価格差）","スプレッドとは、板の最良買い気配（ビッド）と最良売り気配（アスク）の価格差のことで、売買のたびに実質的にかかるコストの一つです。"],["liquidity-pool","流動性プール（リクイディティプール）","流動性プールとは、DEXで取引相手として機能するように、利用者が2種類以上のトークンを預け入れてつくる資金の集まりで、預けた人は取引手数料の一部を受け取ります。"],["market-maker","マーケットメイカー（MM）","マーケットメイカーとは、買い注文と売り注文の両方を板に出し続けて、他の参加者がいつでも売買できる状態を作る事業者やトレーダーのことです。"]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"画面に表示された価格が、なぜ約定価格と違うのか？"},"coin":null,"tool":null,"cta":false},"isolated-margin":{"slug":"isolated-margin","cat":"derivatives","en":"Isolated margin","contentLocale":"ja","term":"分離マージン（アイソレーテッドマージン）","aka":["アイソレーテッドマージン","分離証拠金","isolated margin","分離モード"],"short":"分離マージンとは、ポジションごとに証拠金を割り当てて管理する方式で、そのポジションが清算されても失うのは割り当てた証拠金だけに限られます。","body":["分離マージンでは、ポジションを建てるときに使う証拠金を個別に決めます。損失が出ても、そのポジションに割り当てた証拠金の範囲でしか減らず、口座の他の残高や別のポジションには影響しません。清算されれば、そのポジションの証拠金は失いますが、残りの資金は守られます。",["その代わり、清算までの余裕は割り当てた証拠金だけで決まるため、",["クロスマージン","cross-margin"],"より",["清算価格","liquidation-price"],"が建値に近くなりがちです。",["含み損","unrealized-pnl"],"が膨らんだとき、手動で証拠金を追加すれば清算価格を遠ざけることができます。取引所によっては証拠金の自動追加機能もありますが、使うと実質的に損失の上限が広がります。"],"複数の銘柄を同時に取引する人や、リスクの高い小型銘柄を試す人、1回の取引で失う上限をはっきりさせたい人に向いています。クロスマージンとの切り替えは、ポジションがない状態でしかできない取引所が多いので注意してください。"],"example":["口座に3,000 USDTがあり、BTCとDOGEの",["ロング","long-and-short"],"を分離マージンでそれぞれ500 USDTずつ建てたとします。DOGEが急落してポジションが清算されても、失うのはDOGEに割り当てた500 ",["USDT","usdt"],"（と清算手数料）だけです。BTCのポジションと残りの2,000 USDTはそのまま残ります。クロスマージンだったら、DOGEの損失がBTCのポジションの証拠金も削っていたはずです。"],"mistakes":["分離マージンなら清算されにくいと誤解し、実際には清算価格が近くなることを知らない。","含み損のたびに証拠金を追加し続け、結局は損失の上限を自分で広げてしまう。","ポジションを持ったまま分離とクロスを切り替えようとして、できずに慌てる。"],"faq":[{"q":"分離マージンとクロスマージンはどちらがよいですか？","a":"1回の取引で失う上限をはっきり決めたいなら分離マージン、複数のポジションで証拠金を共有して清算を遠ざけたいならクロスマージンが向いています。初心者には損失の範囲がわかりやすい分離マージンが選ばれることが多いです。"},{"q":"分離マージンで清算されたら口座の残高も失いますか？","a":"いいえ、失うのはそのポジションに割り当てた証拠金だけです。口座の他の資金や別のポジションには影響しません。"}],"title":"分離マージンとは？クロスマージンとの違い","description":"分離マージン（アイソレーテッド）の仕組み、清算時に失う範囲、クロスマージンとの違いと使い分けを具体的な例で解説します。","related":[["cross-margin","クロスマージン","クロスマージンとは、口座内の利用可能な証拠金をすべてのポジションで共有する方式で、清算を遠ざけやすい一方、損失が口座全体に及ぶ可能性があります。"],["portfolio-margin","ポートフォリオマージン","ポートフォリオマージンとは、口座内のすべてのポジションをまとめて評価し、互いに打ち消し合うリスクを考慮して必要な証拠金を計算する方式です。"],["liquidation-price","清算価格（ロスカット価格）","清算価格（ロスカット価格）とは、マーク価格がその水準に達するとポジションが強制ロスカットされる価格のことで、レバレッジと維持証拠金率によって決まります。"],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"]],"lesson":{"id":"E21","slug":"isolated-margin","ep":21,"title":"分離マージン（逐倉）：この取引を独立した小箱に入れる"},"coin":null,"tool":null,"cta":false},"index-price":{"slug":"index-price","cat":"derivatives","en":"Index price","contentLocale":"ja","term":"インデックス価格","aka":["インデックスプライス","指数価格","index price"],"short":"インデックス価格とは、複数の主要な現物取引所の価格を加重平均して算出した、その暗号資産の現物の基準価格のことで、マーク価格や資金調達率の計算に使われます。","body":[[["先物取引","futures-contract"],"所は、自社の先物価格が現物市場からどれだけ離れているかを測るために、外部の基準となる価格を必要とします。それがインデックス価格です。複数の大手",["現物取引","spot-trading"],"所の価格を取得し、",["取引量","trading-volume"],"などに応じて重み付けして平均を出します。"],["インデックス価格は、",["マーク価格","mark-price"],"の土台となり、",["資金調達率","funding-rate"],"の計算や",["限月先物","delivery-futures"],"の決済価格にも使われます。1つの取引所で価格が急に動いたり、データが途絶えたりした場合には、その取引所の重みを下げたり除外したりするルールが設けられているのが一般的です。"],"構成する取引所や重み付けの方法、更新頻度は取引所ごとに違い、多くは契約仕様のページで公開されています。分散型の先物取引所では、オラクルと呼ばれる仕組みで外部の価格をブロックチェーン上に取り込み、同じような役割を果たしています。"],"example":"ある取引所のETHインデックスが、3つの現物取引所の価格から構成されているとします。取引所Aが3,010 USDT（重み50%）、取引所Bが3,000 USDT（重み30%）、取引所Cが2,990 USDT（重み20%）なら、インデックス価格は3,010×0.5＋3,000×0.3＋2,990×0.2＝3,003 USDTです。取引所Cだけが一時的に2,800 USDTまで急落しても、異常値として除外されればインデックスはほぼ変わりません。","mistakes":["インデックス価格を、自分が取引している取引所の現物価格と同じだと思い込む。","インデックスの構成取引所が取引所ごとに違うことを知らず、別の取引所と比べて混乱する。","限月先物の決済価格がインデックスの一定時間の平均で決まることを知らず、満期時の損益に驚く。"],"faq":[{"q":"インデックス価格とマーク価格の違いは何ですか？","a":"インデックス価格は現物市場の基準価格、マーク価格はそれに先物と現物の価格差などを加味した清算判定用の価格です。"},{"q":"インデックス価格の構成はどこで確認できますか？","a":"多くの取引所では、契約仕様やインデックスの説明ページで構成取引所と重みを公開しています。"}],"title":"インデックス価格とは？マーク価格との違い","description":"インデックス価格の意味と計算方法、複数の現物取引所を使う理由、マーク価格や資金調達率との関係を具体例で解説します。","related":[["mark-price","マーク価格","マーク価格とは、先物の含み損益や強制ロスカットの判定に使われる「公正な評価価格」のことで、複数の現物取引所の価格をもとに計算され、一時的な価格操作の影響を受けにくくしています。"],["last-price","最終取引価格（直近約定価格）","最終取引価格（直近約定価格）とは、その取引所の板で最後に売買が成立した価格のことで、取引画面やチャートに表示される通常の「現在値」です。"],["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。"],["oracle","オラクル（ブロックチェーンオラクル）","オラクルとは、価格や天気、試合結果など、ブロックチェーンの外にあるデータをスマートコントラクトに届ける仕組みのことです。"]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"強制決済（清算）：強制終了のボタンを押したのは誰か"},"coin":null,"tool":"/funding-rates","cta":false},"yield-farming":{"slug":"yield-farming","cat":"defi","en":"Yield farming","contentLocale":"ja","term":"イールドファーミング","aka":["イールドファーム","yield farming","流動性マイニング","ファーミング"],"short":"イールドファーミングとは、DeFiのプロトコルに暗号資産を預けたり流動性を提供したりして、手数料や報酬トークンなどの利回りを得る運用方法です。","body":[["典型的な流れは、DEXに",["流動性","liquidity"],"を提供してLPトークンを受け取り、それをさらにファームと呼ばれるコントラクトに預けて報酬トークンを得るというものです。新しいプロトコルが利用者を集めるために、自社の",["ガバナンストークン","governance-token"],"を配ることがよくあります。"],"表示される年利（APRやAPY）は非常に高く見えることがありますが、多くは報酬トークンの価格に依存しています。参加者が増えたり報酬トークンが売られたりすれば、実際の利回りはすぐに下がります。",["リスクは複数重なります。",["スマートコントラクト","smart-contract"],"のハッキング、",["インパーマネントロス","impermanent-loss"],"、報酬トークンの値下がり、複数のプロトコルを組み合わせた場合の連鎖的な失敗などです。利回りの出どころを説明できない案件は避けるのが無難です。"]],"example":["あなたが1万ドル分の流動性を提供し、報酬トークンで年利40%が表示されていたとします。1年間条件が変わらなければ、報酬は4,000ドル分です。しかし報酬トークンの価格が1年で半分になれば、受け取った報酬の価値は約2,000ドルに減ります。さらにインパーマネントロスが600ドル、",["ガス代","gas-fee"],"が合計150ドルかかれば、実質の利益は約1,250ドル、年利にして約12.5%まで下がります。"],"mistakes":["表示年利が将来も続くと考え、報酬トークンの価格下落を計算に入れないこと。","監査や運用実績のない新しいプロトコルに大きな金額を預けること。","報酬の受け取りや再投資のたびにかかるガス代を見落とすこと。"],"faq":[{"q":"イールドファーミングとステーキングの違いは何ですか？","a":"ステーキングはブロックチェーンの検証に参加して報酬を得る仕組みです。イールドファーミングはDeFiのプロトコルに流動性を提供して手数料や報酬トークンを得る運用で、リスクの種類が異なります。"},{"q":"年利が数百%の案件は本当ですか？","a":"一時的に表示されることはありますが、多くは新規発行される報酬トークンによるもので、価格下落とともに急速に下がります。詐欺的な案件も多いため、利回りの出どころを確認しましょう。"}],"title":"イールドファーミングとは？仕組みと利回りの落とし穴","description":"イールドファーミングの意味、LPトークンと報酬トークンの仕組み、高い年利表示に潜むリスクを具体的な計算例で解説します。","related":[["liquidity-pool","流動性プール（リクイディティプール）","流動性プールとは、DEXで取引相手として機能するように、利用者が2種類以上のトークンを預け入れてつくる資金の集まりで、預けた人は取引手数料の一部を受け取ります。"],["apr-vs-apy","APRとAPYの違い（年利・年間利回り）","APRは複利を含まない単純な年利、APYは得た利息を再投資する複利効果を含めた年間利回りで、同じ金利でもAPYの方が高い数字になります。"],["impermanent-loss","インパーマネントロス（変動損失）","インパーマネントロスとは、AMMの流動性プールに資産を預けている間にトークンの価格比が変わることで、単に保有していた場合より資産価値が少なくなる損失のことです。"],["staking","ステーキング","ステーキングとは、プルーフ・オブ・ステーク型のブロックチェーンで暗号資産を預け入れてネットワークの運営に参加し、その対価として報酬を受け取る仕組みです。"]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"mev":{"slug":"mev","cat":"defi","en":"MEV (maximal extractable value)","contentLocale":"ja","term":"MEV（最大抽出可能価値）","aka":["最大抽出可能価値","MEV","Maximal Extractable Value","サンドイッチ攻撃"],"short":"MEV（最大抽出可能価値）とは、ブロックに入れる取引の順番を並べ替えたり、取引を差し込んだりすることで、ブロック生成者や専門のボットが得られる追加の利益のことです。","body":[[["ブロックチェーン","blockchain"],"の取引は、ブロックに取り込まれる前に",["メンプール","mempool"],"と呼ばれる待機場所で公開されています。ボットはここを監視し、利益が出る取引を見つけると、その前後に自分の取引を差し込みます。"],[["アービトラージ","arbitrage"],"や清算の実行のように、市場の効率化に役立つMEVもあります。一方で利用者に直接損をさせるのが、サンドイッチ攻撃です。あなたの買い注文の直前にボットが買って価格を上げ、あなたが高く買った直後に売り抜けます。"],["対策としては、",["スリッページ","slippage"],"許容値を必要以上に大きくしないこと、取引をメンプールに公開せずに送るプライベート送信（MEV保護）に対応したRPCや",["ウォレット","crypto-wallet"],"機能を使うことなどがあります。大きな取引ほど狙われやすくなります。"]],"example":"あなたがDEXで20,000 USDCを使ってトークンを買い、スリッページ許容値を3%に設定したとします。ボットはこの取引をメンプールで見つけ、直前に買って価格を2.5%押し上げます。あなたの取引は許容範囲内なので約定しますが、約2.5%、およそ500 USDC分不利な価格で買うことになります。直後にボットが売り、その差額の多くを利益にします。許容値を0.5%にしていれば、取引は失敗して攻撃は成立しませんでした。","mistakes":["取引が失敗しないよう、スリッページ許容値を大きく設定し続けること。","流動性の薄いプールで、大きな金額を一度に取引すること。","MEVはプロのトレーダーだけの問題で、少額の個人取引には関係ないと考えること。"],"faq":[{"q":"サンドイッチ攻撃にあったかどうかはどう確認できますか？","a":"ブロックエクスプローラーで自分の取引の前後を見て、同じアドレスが直前に買い、直後に売っていれば、サンドイッチ攻撃の可能性が高いです。"},{"q":"中央集権型の取引所でもMEVは起こりますか？","a":"CEXの板取引はブロックチェーン上で処理されないため、ここで説明したオンチェーンのMEVは起こりません。ただし取引所内部の注文処理の公平性は、別の論点として存在します。"}],"title":"MEVとは？サンドイッチ攻撃の仕組みと対策","description":"MEV（最大抽出可能価値）の意味、メンプールを狙うサンドイッチ攻撃の仕組み、スリッページ設定やMEV保護による対策を解説します。","related":[["mempool","メンプール（Mempool）","メンプールとは、送信されたもののまだブロックに取り込まれていない未承認の取引が一時的に待機している場所のことです。"],["slippage","スリッページ","スリッページとは、注文時に想定していた価格と実際に約定した価格との差のことで、主に成行注文や値動きの激しい局面で発生します。"],["dex","DEX（分散型取引所）","DEX（分散型取引所）とは、運営会社が資産を預からず、スマートコントラクトを使ってウォレット同士で直接暗号資産を交換できる取引所です。"],["gas-fee","ガス代（Gas fee）","ガス代とは、イーサリアムなどのブロックチェーンで送金やスマートコントラクトを実行するときに、ネットワークに支払う手数料のことです。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"nft":{"slug":"nft","cat":"defi","en":"NFT (non-fungible token)","contentLocale":"ja","term":"NFT（非代替性トークン）","aka":["非代替性トークン","NFT","ノンファンジブルトークン"],"short":"NFT（非代替性トークン）とは、1つ1つが固有の識別番号を持ち、他と交換可能ではないデジタルトークンで、アートやゲームアイテム、会員権などの所有を表すのに使われます。","body":[[["ビットコイン","bitcoin"],"や1円玉のように、どれも同じ価値で交換できるものを代替可能（ファンジブル）と呼びます。NFTは1枚ごとに異なるIDを持ち、",["ブロックチェーン","blockchain"],"上で誰がどのNFTを持っているかを記録します。",["イーサリアム","ethereum"],"ではERC721やERC1155という規格が使われます。"],"NFTで証明されるのは、多くの場合「そのトークンを持っていること」です。画像そのものは外部のサーバーに保存されていることが多く、著作権や商用利用の権利がNFTの購入で自動的に移るわけではありません。権利の範囲はプロジェクトの規約によります。",["NFTの売買では、偽物のコレクション、偽のミントサイト、NFTの一括承認を悪用した詐欺が多く見られます。購入前に公式のコントラクト",["アドレス","wallet-address"],"を確認し、知らないサイトでの承認には特に注意しましょう。"]],"example":"あなたがNFTマーケットプレイスで0.2 ETHのNFTを購入するとします。ETHが3,000ドルなら600ドルです。数か月後に0.3 ETHで売れたとしても、マーケットプレイス手数料が2.5%、クリエイターロイヤリティが5%なら、差し引かれるのは0.0225 ETHで、受け取るのは0.2775 ETHです。さらにその時点のETH価格が2,000ドルなら555ドルとなり、ETH建てでは利益でも、ドル建てでは購入時の600ドルを下回ります。","mistakes":["NFTを買えば画像の著作権も手に入ると思い込むこと。","名前とサムネイルだけで判断し、偽のコレクションのNFTを購入すること。","マーケットプレイスの「すべてのNFTの承認」を、意味を理解せずに許可すること。"],"faq":[{"q":"NFTの画像はどこに保存されていますか？","a":"多くの場合、画像やデータは外部のサーバーやIPFSなどの分散ストレージに保存され、NFTにはその場所へのリンクが記録されています。一部のプロジェクトは、データをブロックチェーン上に直接記録しています。"},{"q":"NFTはどこで売買できますか？","a":"NFTマーケットプレイスや、NFTに対応した暗号資産取引所で売買できます。どの場所でも、コレクションのコントラクトアドレスが公式のものかを確認しましょう。"}],"title":"NFT（非代替性トークン）とは？仕組みと注意点","description":"NFT（非代替性トークン）の意味、代替可能なトークンとの違い、所有と著作権の関係、売買時の手数料や詐欺への注意点を解説します。","related":[["smart-contract","スマートコントラクト","スマートコントラクトとは、ブロックチェーン上に置かれ、あらかじめ決められた条件が満たされると自動的に実行されるプログラムのことです。"],["token-approval","トークン承認（Approve・アローワンス）","トークン承認とは、DEXなどのスマートコントラクトに、あなたのウォレットから特定のトークンを指定量まで引き出す権限を与える操作です。"],["phishing","フィッシング詐欺","フィッシング詐欺とは、取引所やウォレットを装った偽のサイト、メール、メッセージで、ログイン情報やシードフレーズを入力させたり、悪意ある取引に署名させたりする詐欺です。"],["coin-vs-token","コインとトークンの違い","コインとトークンの違いとは、コインは独自のブロックチェーンのネイティブ資産であり、トークンは既存のブロックチェーン上でスマートコントラクトにより発行される資産だという区別です。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"vasp":{"slug":"vasp","cat":"regulation","en":"VASP (virtual asset service provider)","contentLocale":"ja","term":"VASP（暗号資産サービス提供者）","aka":["暗号資産交換業者","仮想資産サービス提供者","CASP"],"short":"VASPとは、暗号資産の交換、送金、保管などのサービスを業として提供する事業者を指すFATFの用語で、取引所やカストディ業者などが該当します。","body":["VASPはVirtual Asset Service Providerの略で、各国の規制当局はこの考え方をもとに、どの事業者を登録や免許の対象にするかを決めています。日本では金融庁に登録した「暗号資産交換業者」が、EUではMiCAのもとで認可された「CASP（暗号資産サービス提供者）」が、それぞれこれに近い位置づけです。",["VASPとして登録・認可を受けた事業者は、",["本人確認","kyc"],"（KYC）、",["マネーロンダリング対策","aml"],"、",["トラベルルール","travel-rule"],"、顧客資産の分別管理などの義務を負います。要件は国ごとに異なり、ある国で登録されていても、別の国の居住者に対してサービスを提供できるとは限りません。"],"利用者にとっては、取引所が自分の住む国で登録や認可を受けているかを確認することが、トラブル時の保護や手続きの面で大きな違いになります。登録番号や当局の公開リストで確認できるのが一般的です。"],"example":"あなたが日本に住んでいて、取引所Aと取引所Bを比べているとします。取引所Aは金融庁の暗号資産交換業者登録一覧に載っており、取引所Bは海外の別の国でだけ登録されています。取引所Aでは顧客資産の分別管理や国内法にもとづく手続きが適用されます。一方、取引所Bに100,000円分の資産を預けてトラブルが起きた場合、日本の制度の保護は受けられず、相手国の制度や取引所の規約に従うことになります。どちらを使うかは、こうした違いを理解したうえで判断する必要があります。","mistakes":["どこかの国で登録されていれば、自分の国でも同じように保護されると考える。","取引所のサイトに書かれた「ライセンス取得」という表示だけを信じ、当局の公開リストで確認しない。","登録の範囲が現物取引だけなのか、先物なども含むのかを確認しない。"],"faq":[{"q":"日本で登録されている暗号資産交換業者はどう確認できますか？","a":"金融庁が公開している暗号資産交換業者の登録一覧で確認できます。取引所の名称だけでなく、運営会社名も照らし合わせると確実です。"},{"q":"VASPとCASPの違いは何ですか？","a":"VASPはFATFが使う国際的な用語で、CASPはEUのMiCAで使われる用語です。指している範囲はおおむね近いですが、具体的な定義は制度ごとに異なります。"}],"title":"VASPとは？暗号資産サービス提供者の意味","description":"VASP（暗号資産サービス提供者）の意味、日本の暗号資産交換業者やEUのCASPとの関係、登録状況を確認すべき理由を解説します。","related":[["kyc","KYC（本人確認）","KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。"],["mica","MiCA（EU暗号資産市場規則）","MiCAとは、EU全体で暗号資産の発行者とサービス提供者に共通のルールを定めた規則で、ステーブルコインや取引所などの認可、情報開示、利用者保護を定めています。"],["travel-rule","トラベルルール","トラベルルールとは、暗号資産を取引所間などで送るときに、送金人と受取人の氏名などの情報を事業者同士で共有することを求める国際的なルールです。"],["centralized-exchange","中央集権型取引所（CEX）","中央集権型取引所（CEX）とは、運営会社が利用者の資産を預かり、注文の照合や入出金を管理する暗号資産取引所のことです。"]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"本物の扉を見極める：やみくもに口座開設しないこと"},"coin":null,"tool":"/topics/compliant-exchanges","cta":false},"mica":{"slug":"mica","cat":"regulation","en":"MiCA (EU Markets in Crypto-Assets)","contentLocale":"ja","term":"MiCA（EU暗号資産市場規則）","aka":["MiCA規則","Markets in Crypto-Assets","ミカ"],"short":"MiCAとは、EU全体で暗号資産の発行者とサービス提供者に共通のルールを定めた規則で、ステーブルコインや取引所などの認可、情報開示、利用者保護を定めています。","body":[["MiCAはMarkets in Crypto-Assetsの略です。",["ステーブルコイン","stablecoin"],"に関するルールは2024年6月30日から、",["暗号資産サービス提供者","vasp"],"（CASP）に関するルールは2024年12月30日から適用されました。各国には最長で2026年7月1日までの移行期間が認められています。"],"MiCAで認可を受けたCASPは、1つのEU加盟国の認可を使って他の加盟国にもサービスを提供できる「パスポート」の仕組みを利用できます。ステーブルコインについては、発行体に準備資産や償還に関する厳しい要件が課されています。","MiCAの影響で、一部の取引所はEU居住者向けに、要件を満たさないステーブルコインの取扱いを制限するなどの対応をしました。EU以外に住む人に直接適用されるわけではありませんが、世界の大手取引所の商品設計に影響を与えています。"],"example":"あるステーブルコイン発行体が、EUで1億ユーロ相当のステーブルコインを発行しているとします。MiCAのもとでは、この発行体は認可を受け、準備資産を分別して保有し、保有者が額面で償還を求められるようにする必要があります。もし発行体が認可を受けていなければ、EUのCASPはそのステーブルコインの取扱いを制限しなければならない場合があります。その結果、EU居住者がある取引所で1,000ユーロ分を保有していても、その銘柄の新規購入ができなくなる、といったことが起こり得ます。","mistakes":["MiCAが日本など、EU以外の国にもそのまま適用されると考える。","移行期間中の事業者と、すでにMiCAの認可を受けた事業者を同じように扱う。","MiCAの認可があれば、投資の損失まで保護されると考えてしまう。"],"faq":[{"q":"MiCAはいつから適用されていますか？","a":"ステーブルコインのルールは2024年6月30日から、CASPのルールは2024年12月30日から適用されています。国ごとに最長2026年7月1日までの移行期間があります。"},{"q":"MiCAでUSDTはどうなりましたか？","a":"MiCAの要件を満たしていないステーブルコインについて、一部の取引所がEU居住者向けの取扱いを制限しました。対応は取引所ごとに異なるため、利用する取引所の案内を確認してください。"}],"title":"MiCAとは？EUの暗号資産規制の意味と影響","description":"MiCA（EU暗号資産市場規則）の意味、適用開始日と移行期間、ステーブルコインや取引所への影響をわかりやすく解説します。","related":[["vasp","VASP（暗号資産サービス提供者）","VASPとは、暗号資産の交換、送金、保管などのサービスを業として提供する事業者を指すFATFの用語で、取引所やカストディ業者などが該当します。"],["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"],["usdc","USDC（USDコイン）","USDCとは、米国のCircle社が発行する米ドル連動型のステーブルコインで、現金と米国短期国債などを裏付けに1 USDCが約1ドルになるよう設計されています。"],["kyc","KYC（本人確認）","KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。"]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"本物の扉を見極める：やみくもに口座開設しないこと"},"coin":null,"tool":null,"cta":false},"dual-investment":{"slug":"dual-investment","cat":"exchange-features","en":"Dual investment","contentLocale":"ja","term":"デュアル投資（Dual Investment）","aka":["デュアルインベストメント","Dual Investment","二重通貨投資"],"short":"デュアル投資とは、あらかじめ決めた価格（ターゲット価格）と期日を設定し、期日の価格に応じて元本と利息を暗号資産かステーブルコインのどちらかで受け取る仕組み商品です。","body":[["デュアル投資には、",["ステーブルコイン","stablecoin"],"を預けて安く買うことを狙う「安値で買う」タイプと、",["暗号資産","cryptocurrency"],"を預けて高く売ることを狙う「高値で売る」タイプがあります。どちらも、期日の価格がターゲット価格に届いたかどうかで、受け取る通貨が変わります。"],["仕組みとしては、",["オプション","options"],"の売り手になって、その対価（プレミアム）を高い利回りとして受け取るのに近い商品です。そのため、価格が大きく動いても得られる利益は利息分に限られる一方、相場が逆に動いたときは不利な価格で交換されます。"],"期日までは途中解約できないものがほとんどです。表示される年率は短い期間を年率に換算したものなので、実際に受け取る利息の金額を計算してから判断しましょう。条件や名称は取引所によって異なります。"],"example":["BTCが60,000 USDTのときに、あなたが「安値で買う」タイプに6,000 USDTを預け、ターゲット価格58,000 ",["USDT","usdt"],"、期間7日、年率30%の条件を選んだとします。7日分の利息は6,000×0.30×7÷365で約34.5 USDTです。期日の価格が58,000を上回っていれば、6,034.5 USDTを受け取ります。58,000以下だった場合は、6,034.5 USDTを58,000で割った約0.104 BTCを受け取ります。もし期日の価格が52,000まで下がっていれば、0.104 BTCの価値は約5,410 USDTで、利息を含めても元本を下回ります。"],"mistakes":["高い年率表示を見て、元本保証の預金商品だと誤解する。","相場が大きく上がっても、利益は利息分だけに限られることを理解していない。","受け取る通貨が変わることを想定せず、必要な時期に必要な通貨を用意できなくなる。"],"faq":[{"q":"デュアル投資は元本保証ですか？","a":"元本保証ではありません。受け取る通貨が変わるため、期日の価格によってはステーブルコイン建てや暗号資産建てで見て元本を下回ることがあります。"},{"q":"デュアル投資は途中で解約できますか？","a":"多くの取引所では期日まで解約できません。一部で早期償還の仕組みがある場合も、条件が不利になることが一般的です。"}],"title":"デュアル投資とは？仕組みとリスクを計算例で解説","description":"デュアル投資の意味と仕組み、安値で買う・高値で売るタイプの違い、受け取り通貨が変わるリスクを具体的な計算例で解説します。","related":[["options","オプション取引（暗号資産オプション）","オプション取引とは、ある資産を将来の決められた日に、決められた価格（権利行使価格）で買う権利（コール）または売る権利（プット）を売買する取引です。"],["crypto-earn","暗号資産の運用サービス（Earn）","暗号資産の運用サービス（Earn）とは、取引所に預けた暗号資産を貸し出しやステーキングなどに回し、利息や報酬を受け取れる取引所の商品群のことです。"],["apr-vs-apy","APRとAPYの違い（年利・年間利回り）","APRは複利を含まない単純な年利、APYは得た利息を再投資する複利効果を含めた年間利回りで、同じ金利でもAPYの方が高い数字になります。"],["volatility","ボラティリティ（価格変動率）","ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。"]],"lesson":null,"coin":null,"tool":null,"cta":false},"unified-trading-account":{"slug":"unified-trading-account","cat":"exchange-features","en":"Unified trading account (UTA)","contentLocale":"ja","term":"統合取引口座（UTA）","aka":["ユニファイドトレーディングアカウント","UTA","統合アカウント","統一口座"],"short":"統合取引口座（UTA）とは、現物、先物、オプションなどの取引を1つの口座でまとめて行い、口座内の資産全体を証拠金として共有できる取引所の口座形態です。","body":[["従来の取引所では、現物口座、先物口座などが分かれていて、取引のたびに資金を振り替える必要がありました。統合取引口座では、保有しているUSDT、",["BTC","bitcoin"],"、ETHなどを一括で管理し、それぞれの資産に一定の掛け目をかけた価値を証拠金として使えます。BybitやOKXなどが統合型の口座を提供しています。"],["メリットは資金効率です。現物で持っているBTCを先物の証拠金に使えたり、あるポジションの",["含み益","unrealized-pnl"],"で別のポジションの証拠金を補えたりします。上級者向けには、ポジション全体のリスクで証拠金を計算する",["ポートフォリオマージン","portfolio-margin"],"が用意されていることもあります。"],["反面、口座全体がつながっているため、1つのポジションの損失が口座内の他の資産にも影響します。",["分離マージン","isolated-margin"],"（アイソレーテッド）で管理したい取引は、別の",["サブアカウント","sub-account"],"に分けるなどの工夫が必要です。資産ごとの掛け目や清算のルールは取引所によって異なります。"]],"example":"あなたの統合取引口座に、0.1 BTC（BTC＝60,000 USDTで6,000 USDT相当）と1,000 USDTがあるとします。取引所がBTCの掛け目を95%としていれば、BTCの証拠金としての価値は5,700 USDTで、合計6,700 USDTを証拠金として使えます。この状態でETHの先物ポジションに大きな含み損が出ると、口座全体の証拠金が不足し、USDTだけでなく保有しているBTCも清算の対象になる可能性があります。現物で長期保有したいBTCを守りたいなら、先物用の資金は別の口座に分けることが考えられます。","mistakes":["統合取引口座に長期保有用の現物を置いたまま、高いレバレッジで先物取引をする。","資産ごとの掛け目を確認せず、保有額のすべてが証拠金として使えると考える。","クロスマージンの状態で、1つのポジションの損失が口座全体に及ぶことを理解していない。"],"faq":[{"q":"統合取引口座に切り替えるメリットは何ですか？","a":"資金を振り替えずに複数の商品を取引でき、口座内の資産をまとめて証拠金として使える点です。資金効率は上がりますが、リスクも口座全体で共有されます。"},{"q":"統合取引口座で現物の資産が清算されることはありますか？","a":"証拠金として使われている場合、先物の損失で証拠金が不足すると、現物の資産も清算の対象になることがあります。条件は取引所ごとに確認が必要です。"}],"title":"統合取引口座（UTA）とは？仕組みとリスク","description":"統合取引口座（UTA）の意味と仕組み、資産の掛け目と証拠金の考え方、現物資産が清算に巻き込まれるリスクと対策を解説します。","related":[["cross-margin","クロスマージン","クロスマージンとは、口座内の利用可能な証拠金をすべてのポジションで共有する方式で、清算を遠ざけやすい一方、損失が口座全体に及ぶ可能性があります。"],["portfolio-margin","ポートフォリオマージン","ポートフォリオマージンとは、口座内のすべてのポジションをまとめて評価し、互いに打ち消し合うリスクを考慮して必要な証拠金を計算する方式です。"],["sub-account","サブアカウント","サブアカウントとは、1つのメインアカウントの下に作成できる独立した口座で、資金や取引、APIキーを用途ごとに分けて管理するための取引所の機能です。"],["margin-trading","証拠金取引（マージン取引）","証拠金取引（マージン取引）とは、証拠金を担保として取引所から資金や暗号資産を借り、手持ちの資金より大きな金額で売買する取引方法です。"]],"lesson":null,"coin":null,"tool":null,"cta":true},"withdrawal-fee":{"slug":"withdrawal-fee","cat":"exchange-features","en":"Withdrawal fee","contentLocale":"ja","term":"出金手数料","aka":["送金手数料","引き出し手数料","withdrawal fee"],"short":"出金手数料とは、取引所から外部のウォレットや他の取引所へ暗号資産を送るときに差し引かれる手数料で、主にブロックチェーンのネットワーク手数料をまかなうためのものです。","body":[["取引所から",["暗号資産","cryptocurrency"],"を出金すると、取引所は",["ブロックチェーン","blockchain"],"上で送金を行い、その",["ガス代","gas-fee"],"などを負担します。出金手数料はこのコストに取引所の設定を加えたもので、多くの場合「0.0002 ",["BTC","bitcoin"],"」「1 ",["USDT","usdt"],"」のように固定の枚数で決められています。"],["同じ通貨でも、どのネットワークで送るかによって手数料は大きく変わります。たとえばUSDTは、",["イーサリアム","ethereum"],"（ERC20）、トロン（TRC20）、各種レイヤー2などで送れますが、イーサリアムは混雑時に手数料が高くなりがちです。送金先が対応しているネットワークの中から選ぶ必要があります。"],"取引所によっては、同じ取引所の利用者同士の内部送金を無料にしていたり、国内取引所では日本円の出金に別途手数料がかかったりします。少額の出金では手数料の割合が大きくなるため、まとめて出金するほうが効率的です。"],"example":"あなたが200 USDTを取引所から別の取引所へ送るとします。ERC20での出金手数料が5 USDT、TRC20が1 USDT、あるレイヤー2が0.5 USDTだとすると、受け取れる金額はそれぞれ195 USDT、199 USDT、199.5 USDTです。ERC20を選ぶと手数料は金額の2.5%にもなります。ただし、送金先の取引所がそのレイヤー2での入金に対応していなければ、資金が届かなかったり、取り戻すのに手間がかかったりします。手数料が一番安いネットワークではなく、送金先も対応しているネットワークの中で一番安いものを選ぶのがポイントです。","mistakes":["手数料の安さだけでネットワークを選び、送金先が対応していないチェーンに送ってしまう。","少額を何度も出金し、そのたびに固定の手数料を払って割高にしてしまう。","出金手数料が差し引かれることを忘れ、受取額が足りずに次の取引ができなくなる。"],"faq":[{"q":"出金手数料はなぜ取引所ごとに違うのですか？","a":"ネットワーク手数料に加えて、取引所がどのくらいの手数料を設定するかが異なるためです。出金画面にその時点の手数料が表示されるので、送金前に確認してください。"},{"q":"出金手数料を安くする方法はありますか？","a":"送金先が対応している中で手数料の安いネットワークを選ぶ、出金をまとめる、同じ取引所内の送金なら内部送金を使う、といった方法があります。"}],"title":"出金手数料とは？ネットワーク選びと節約のコツ","description":"暗号資産の出金手数料の意味、ネットワークによって手数料が変わる理由、送金先の対応確認と手数料を抑えるコツを具体例で解説します。","related":[["gas-fee","ガス代（Gas fee）","ガス代とは、イーサリアムなどのブロックチェーンで送金やスマートコントラクトを実行するときに、ネットワークに支払う手数料のことです。"],["blockchain-network","送金ネットワーク（チェーン選択）","送金ネットワークとは、暗号資産を入出金するときにどのブロックチェーン上で送るかを指定する項目で、送金側と受取側で一致させる必要があります。"],["maker-taker-fees","メイカー手数料・テイカー手数料（Maker/Taker）","メイカー手数料・テイカー手数料とは、板に注文を置いて流動性を提供した側（メイカー）と、板の注文を即座に約定させた側（テイカー）で分けて設定される取引手数料のことです。"],["layer-2","レイヤー2（L2）","レイヤー2（L2）とは、イーサリアムなどのレイヤー1の上で取引をまとめて処理し、その結果をL1に記録することで、手数料を下げ処理を速くする仕組みです。"]],"lesson":{"id":"E08","slug":"sell-vs-withdraw","ep":8,"title":"売却したのに、なぜ銀行口座にお金が入っていないの？"},"coin":null,"tool":"/rates","cta":false}});
